<script module lang="ts">
/**
 * JsonTree.Entry: one value of the tree, a leaf or a container with its entries.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/json-tree.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { Icon, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/json-tree.module.css'
import JsonTreeEntry from './JsonTreeEntry.svelte'

export interface JsonTreeEntryProps {
  /**
   * The key or index it sits under.
   */
  name?: string
  value: unknown
  depth: number
  defaultDepth: number
}
</script>

<script lang="ts">
let { name, value, depth, defaultDepth }: JsonTreeEntryProps = $props()
const joined = joinSlot(undefined, () => ({ name: name }))
// svelte-ignore state_referenced_locally
let open = $state(depth < defaultDepth)
const entries = $derived(
  typeof value === 'object' && value !== null
    ? Array.isArray(value)
      ? value.map((item: unknown, index: number) => [String(index), item] as const)
      : Object.entries(value)
    : null,
)
const kind = $derived(
  value === null
    ? 'null'
    : typeof value === 'string'
      ? 'string'
      : typeof value === 'number'
        ? 'number'
        : typeof value === 'boolean'
          ? 'boolean'
          : 'null',
)
const spelled = $derived(kind === 'string' ? JSON.stringify(value) : String(value))
const summary = $derived(
  Array.isArray(value)
    ? `[…] ${value.length} ${value.length === 1 ? 'item' : 'items'}`
    : `{…} ${entries?.length ?? 0} ${entries?.length === 1 ? 'key' : 'keys'}`,
)
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if entries === null
    }<li class={styles.row}
      >{#if name !== undefined
        }<span class={styles.key}>{name}<span class={styles.colon}>:</span></span
      >{/if
      }<span class={styles.value} data-kind={kind}>{spelled}</span
    ></li
  >{:else if entries.length === 0
    }<li class={styles.row}
      >{#if name !== undefined
        }<span class={styles.key}>{name}<span class={styles.colon}>:</span></span
      >{/if
      }<span class={styles.summary}>{Array.isArray(value) ? '[]' : '{}'}</span
    ></li
  >{:else
    }<li class={styles.row}
      ><button
        class={styles.toggle}
        type="button"
        aria-expanded={open}
        onclick={() => { open = !open }}
        ><span class={styles.chevron} aria-hidden="true"><Icon name="next" size="sm" /></span
        >{#if name !== undefined
          }<span class={styles.key}>{name}<span class={styles.colon}>:</span></span
        >{/if
        }<span class={styles.summary}>{summary}</span
      ></button
      >{#if open
        }<ul class={styles.children}
          >{#each entries as pair (pair[0])
            }<JsonTreeEntry name={pair[0]} value={pair[1]} depth={depth + 1} {defaultDepth}
          />{/each
        }</ul
      >{/if
    }</li
  >{/if
}{/if
}{@render joined.end?.()}
